using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;
internal static class ImportUpdateTests {
    static int checks;static JavaScriptSerializer json=new JavaScriptSerializer();
    static void Need(bool value,string message){checks++;if(!value)throw new Exception(message);}
    static void Pump(int ms){var timer=Stopwatch.StartNew();while(timer.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(3);}}
    static string Zip(string folder,string name,Dictionary<string,string> files){string path=Path.Combine(folder,name);using(var archive=ZipFile.Open(path,ZipArchiveMode.Create)){var entries=new List<SoftwareFile>();foreach(var pair in files){var bytes=Encoding.UTF8.GetBytes(pair.Value);var entry=archive.CreateEntry(pair.Key);using(var output=entry.Open())output.Write(bytes,0,bytes.Length);string source=Path.Combine(folder,Guid.NewGuid().ToString("N"));File.WriteAllBytes(source,bytes);entries.Add(new SoftwareFile{path=pair.Key,bytes=bytes.Length,sha256=SoftwareUpdate.Hash(source)});File.Delete(source);}using(var writer=new StreamWriter(archive.CreateEntry("update-manifest.json").Open()))writer.Write(json.Serialize(new SoftwareManifest{product="CodexHub-program-update",version="1.7.0.4",files=entries.ToArray()}));}return path;}
    static object Update(string folder){string root=Path.Combine(folder,"installed"),state=Path.Combine(folder,"state");Directory.CreateDirectory(root);Directory.CreateDirectory(state);File.WriteAllText(Path.Combine(root,"CodexLiveBackground.exe"),"old program");File.WriteAllText(Path.Combine(root,"manifest.json"),"{\"version\":\"1.7.0.2\",\"files\":[]}");
        File.WriteAllText(Path.Combine(root,".codex-background-install.json"),json.Serialize(new{productId="codex-live-background/exe",root=root,files=new[]{"CodexLiveBackground.exe","manifest.json",".codex-background-install.json"}}));var keep=new Dictionary<string,string>();foreach(string relative in new[]{"wallpapers/original.mp4","source/assets/pets/deepseek-fat-fish/086.webm","engine/runtime/node/node.exe","startup/DreamSkinPortHook.exe"}){string path=Path.Combine(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,"original "+relative);keep[path]=SoftwareUpdate.Hash(path);}foreach(string name in new[]{"pet-settings.json","wallpaper-library.json","config.toml","original-user-wallpaper.png"}){string path=Path.Combine(state,name);File.WriteAllText(path,"preserve "+name);keep[path]=SoftwareUpdate.Hash(path);}
        foreach(string path in new[]{"wallpapers/original.mp4","source/assets/pets/a/pet.json","../escape.cs","engine/runtime/node/node.exe","startup/DreamSkinPortHook.exe","pet-settings.json"})Need(!SoftwareUpdate.Allowed(path),"Update permits a material, setting or external path: "+path);
        bool blocked=false;try{SoftwareUpdate.ReleaseUri("https://example.com/evil.zip");}catch(InvalidDataException){blocked=true;}Need(blocked,"Foreign release endpoint accepted");
        string bad=Zip(folder,"bad.zip",new Dictionary<string,string>{{"CodexLiveBackground.exe","new"},{"source/assets/pets/a/pet.json","changed"}});var request=new SoftwareUpdateRequest{Root=root,StateRoot=state,Archive=bad,Sha256=SoftwareUpdate.Hash(bad)};blocked=false;try{SoftwareUpdate.Apply(request,s=>{});}catch(InvalidDataException){blocked=true;}Need(blocked&&File.ReadAllText(Path.Combine(root,"CodexLiveBackground.exe"))=="old program","Invalid update changed the program");
        string good=Zip(folder,"good.zip",new Dictionary<string,string>{{"CodexLiveBackground.exe","new program"},{"engine/scripts/new.mjs","new engine"}});request.Archive=good;request.Sha256=SoftwareUpdate.Hash(good);blocked=false;try{SoftwareUpdate.Apply(request,s=>{},count=>{if(count==2)throw new IOException("fixture failure");});}catch(IOException){blocked=true;}Need(blocked&&File.ReadAllText(Path.Combine(root,"CodexLiveBackground.exe"))=="old program"&&!File.Exists(Path.Combine(root,"engine/scripts/new.mjs")),"Failed update did not roll program files back");
        SoftwareUpdate.Apply(request,s=>{});Need(File.ReadAllText(Path.Combine(root,"CodexLiveBackground.exe"))=="new program","Program update failed");Need(Convert.ToString(json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"manifest.json")))["version"])=="1.7.0.4","Updated inventory version is wrong");var inventory=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"manifest.json")));var marker=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,".codex-background-install.json")));var inventoryPaths=((System.Collections.IEnumerable)inventory["files"]).Cast<Dictionary<string,object>>().Select(f=>Convert.ToString(f["path"])).Concat(new[]{"manifest.json",".codex-background-install.json"}).ToArray();Need(((System.Collections.IEnumerable)marker["files"]).Cast<object>().All(f=>inventoryPaths.Contains(Convert.ToString(f))),"Update inventory paths prevent later uninstall");foreach(var item in keep)Need(SoftwareUpdate.Hash(item.Key)==item.Value,"Update changed media/settings/service/runtime: "+item.Key);blocked=false;try{SoftwareUpdate.Apply(request,s=>{});}catch(InvalidDataException){blocked=true;}Need(blocked,"Same version update should be idempotently rejected");return new{bytePreservation=keep.Count,programRollback=true,materialsAndPreferencesUntouched=true,serviceAndRuntimeUntouched=true};
    }
    [STAThread]static int Main(string[] args){string report=args[0],root=args[1];try{Application.EnableVisualStyles();string folder=Path.Combine(Path.GetTempPath(),"HubTest-"+Guid.NewGuid().ToString("N").Substring(0,12));Directory.CreateDirectory(folder);var paper=new WallpaperLibrary(Path.Combine(folder,"paper"));paper.Add(Path.Combine(folder,"active-theme","dream-reference.jpg"),"纸上微光","recovered",null,null);paper.Add(Path.Combine(folder,"personal.jpg"),"纸上微光","local",null,null);paper=new WallpaperLibrary(Path.Combine(folder,"paper"));Need(paper.Snapshot().Count==1&&paper.Snapshot()[0].Source=="local"&&paper.CurrentThemeMigrated,"Retired recovered paper wallpaper persists or user import was removed");Need(new WallpaperLibrary(Path.Combine(folder,"paper")).Snapshot().Count==1,"Paper entry returned after reopening");
        var paths=Enumerable.Range(0,350).Select(i=>Path.Combine(folder,"wallpapers",i+".png")).ToArray();var before=new WallpaperLibrary(Path.Combine(folder,"baseline"));var clock=Stopwatch.StartNew();foreach(string path in paths)before.Add(path,null,"local",null,null);long blocking=clock.ElapsedMilliseconds;
        long returned,maxGap=0,previous=0;int beats=0;using(var manager=(Form)Activator.CreateInstance(typeof(Manager),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{false},null))using(var heartbeat=new System.Windows.Forms.Timer{Interval=8}){IntPtr handle=manager.Handle;var target=(Manager)manager;clock.Restart();heartbeat.Tick+=delegate{long now=clock.ElapsedMilliseconds;if(previous>0)maxGap=Math.Max(maxGap,now-previous);previous=now;beats++;};heartbeat.Start();target.ImportWallpaperFiles(paths);returned=clock.ElapsedMilliseconds;while(target.ImportingWallpapers&&clock.ElapsedMilliseconds<10000)Pump(5);Pump(50);Need(!target.ImportingWallpapers&&returned<100,"Batch import blocked the UI thread: "+returned);Need(beats>0&&maxGap<200,"Batch import stopped the UI heartbeat: "+maxGap);var library=(WallpaperLibrary)typeof(Manager).GetField("library",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(manager);Need(library.Snapshot().Count==350,"Batch import lost records");Need(!manager.Visible,"Import proof activated a manager window");}
        var packs=PetPack.Discover(root,Path.Combine(folder,"empty-state"));Need(!packs.Any(p=>p.Id=="xiaolemi"),"Removed pet is still listed");Need(packs.First(p=>p.Id=="deepseek").Name=="鲸鱼娘","Old DeepSeek name is still displayed");using(var pet=PetWindow.Create(packs.First(p=>p.Id=="deepseek-fat-fish"),new PetPreferences{CodexOnly=false,Scale=100,Sound=false,Roaming=false,PositionVersion=1},root)){Need(Math.Abs(pet.PetFactor-1.12)<.001,"Whale maid 100% is not the previous 80%");Need(pet.CapsuleFactor==1,"Maid size calibration resized the capsule");}
        string sourceFolder=Path.Combine(folder,"builtin-source");Directory.CreateDirectory(sourceFolder);string original=Path.Combine(sourceFolder,"rain-sakura.mp4");File.WriteAllText(original,"verified preexisting media");var remote=new WallpaperEntry{Path=Path.Combine(sourceFolder,"cover.jpg"),Remote=new BuiltinRemoteAsset{file="rain-sakura.mp4",url="https://github.com/chenyan-image/codex-live-background/releases/download/v1.7.0-preview.4/rain-sakura.mp4",bytes=new FileInfo(original).Length,sha256=SoftwareUpdate.Hash(original)}};Need(BuiltinDownloads.Ensure(remote,Path.Combine(folder,"builtin-cache"),message=>{throw new Exception("Existing material was downloaded again");})==original,"Valid existing built-in video was not reused");var update=Update(folder);File.WriteAllText(report,json.Serialize(new{pass=true,checks,oldSynchronousImportMs=blocking,newImportReturnMs=returned,uiHeartbeatMaxGapMs=maxGap,update,paperRecordRemoved=true,localSameNamePreserved=true,maidBaselinePercent=80,displayRange="70-150",physicalMouseNotSimulated=true}));return 0;
    }catch(Exception e){File.WriteAllText(report,json.Serialize(new{pass=false,checks,error=e.ToString()}));return 1;}}
}
